```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::types::{FeedDocument, FetchFailure};
use crate::aap::caps::{http_client, state_rw};

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input received, under the shared key `last-input`.
        state_rw::put("last-input", &subscriptions.urls.join("\n"));

        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls.iter() {
            match http_client::fetch(url) {
                Ok(body) => documents.push(FeedDocument {
                    url: url.clone(),
                    body,
                }),
                Err(error) => failures.push(FetchFailure {
                    url: url.clone(),
                    error,
                }),
            }
        }

        FeedBatch { documents, failures }
    }
}

export!(Node);
```

